import crypto from 'crypto';
import fs from 'fs';
import path from 'path';

/*
 * Key vault (prototype custody model)
 * -----------------------------------
 * Users' ECC private keys are generated by the server at registration.
 * They are never stored in the clear: each one is sealed with AES-256-GCM
 * under a master key (KEK) taken from the MASTER_KEY environment variable.
 *
 * HONEST LIMITATION: because the server can unseal these keys, this is a
 * *custodial* design. A production system would keep the private key on
 * the patient's device (or in an HSM/KMS) so the server could never read
 * a record on its own. The consent and audit checks in server.ts are what
 * gate server-side decryption here.
 */

const DEV_KEY_FILE = path.resolve(process.cwd(), '.dev-master-key');

function loadMasterKey(): Buffer {
  const fromEnv = process.env.MASTER_KEY;
  if (fromEnv) {
    const key = /^[0-9a-fA-F]{64}$/.test(fromEnv)
      ? Buffer.from(fromEnv, 'hex')
      : Buffer.from(fromEnv, 'base64');
    if (key.length !== 32) {
      throw new Error('MASTER_KEY must be 32 bytes (64 hex chars or base64).');
    }
    return key;
  }

  if (process.env.NODE_ENV === 'production') {
    throw new Error('MASTER_KEY is required in production.');
  }

  // Development convenience: a random key persisted next to the project
  // (git-ignored) so sealed keys survive restarts.
  try {
    if (fs.existsSync(DEV_KEY_FILE)) {
      return Buffer.from(fs.readFileSync(DEV_KEY_FILE, 'utf8').trim(), 'hex');
    }
    const key = crypto.randomBytes(32);
    fs.writeFileSync(DEV_KEY_FILE, key.toString('hex'), { mode: 0o600 });
    console.warn('[keyVault] MASTER_KEY not set - generated a dev key in .dev-master-key');
    return key;
  } catch {
    console.warn('[keyVault] MASTER_KEY not set - using a temporary in-memory key');
    return crypto.randomBytes(32);
  }
}

let masterKey: Buffer | null = null;
const kek = (): Buffer => (masterKey ??= loadMasterKey());

/** Seal a secret string (e.g. a PEM private key). Format: v1.iv.tag.ciphertext (base64). */
export function sealSecret(plaintext: string, aad = ''): string {
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', kek(), iv);
  if (aad) cipher.setAAD(Buffer.from(aad, 'utf8'));
  const ct = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return ['v1', iv.toString('base64'), tag.toString('base64'), ct.toString('base64')].join('.');
}

export function openSecret(sealed: string, aad = ''): string {
  const [version, iv, tag, ct] = sealed.split('.');
  if (version !== 'v1' || !iv || !tag || !ct) throw new Error('Unsupported sealed secret format');
  const decipher = crypto.createDecipheriv('aes-256-gcm', kek(), Buffer.from(iv, 'base64'));
  if (aad) decipher.setAAD(Buffer.from(aad, 'utf8'));
  decipher.setAuthTag(Buffer.from(tag, 'base64'));
  return Buffer.concat([decipher.update(Buffer.from(ct, 'base64')), decipher.final()]).toString('utf8');
}

/** Keyed hash for low-entropy identifiers (e.g. Aadhaar): HMAC-SHA256 under a key derived from the master key. */
export function keyedHash(label: string, value: string): string {
  const key = Buffer.from(crypto.hkdfSync('sha256', kek(), Buffer.alloc(0), Buffer.from(`fedtrustmed:${label}`), 32));
  return crypto.createHmac('sha256', key).update(value).digest('hex');
}

/** JWT signing secret: JWT_SECRET env var (required in production), else a random per-process secret. */
export function resolveJwtSecret(): string {
  const fromEnv = process.env.JWT_SECRET;
  if (fromEnv && fromEnv.length >= 32) return fromEnv;
  if (process.env.NODE_ENV === 'production') {
    throw new Error('JWT_SECRET (min 32 chars) is required in production.');
  }
  console.warn('[security] JWT_SECRET not set (or < 32 chars) - using a random secret; sessions reset on restart.');
  return crypto.randomBytes(48).toString('hex');
}

/** Deterministic 32-byte sub-key (HKDF) for a label, e.g. a per-organisation ledger signing seed. */
export function deriveKeyMaterial(label: string): Buffer {
  return Buffer.from(crypto.hkdfSync('sha256', kek(), Buffer.alloc(0), Buffer.from(`fedtrustmed:${label}`), 32));
}
